export const ALL_SKILLS = Object.keys(SKILL_DB);

export function extractSkills(text: string): string[] {
  const lower = " " + text.toLowerCase() + " ";
  const found: string[] = [];
  for (const [skill, aliases] of Object.entries(SKILL_DB)) {
    for (const a of aliases) {
      if (lower.includes(a)) {
        found.push(skill);
        break;
      }
    }
  }
  return [...new Set(found)];
}

